/*
 * vuln_drv.c — Fictional vulnerable kernel module for training
 *
 * This driver intentionally contains a use-after-free vulnerability
 * in the VULN_USE / VULN_FREE race path. Load this in the training
 * lab kernel to test the exploit.
 *
 * Build:  make -C /lib/modules/$(uname -r)/build M=$(pwd) modules
 * Load:   insmod vuln_drv.ko
 * Device: /dev/vuln_drv (created via udev or manual mknod)
 */

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/fs.h>
#include <linux/device.h>
#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/mutex.h>
#include <linux/ioctl.h>

#define VULN_DRV_MAGIC 0xDEAD

#define VULN_ALLOC   _IOW(VULN_DRV_MAGIC, 1, struct vuln_alloc_arg)
#define VULN_FREE    _IOW(VULN_DRV_MAGIC, 2, int)
#define VULN_USE     _IOR(VULN_DRV_MAGIC, 3, struct vuln_use_arg)
#define VULN_EDIT    _IOW(VULN_DRV_MAGIC, 4, struct vuln_edit_arg)

struct vuln_alloc_arg {
    uint32_t size;
    uint32_t id;
};

struct vuln_use_arg {
    uint32_t id;
    char     *buf;
    uint32_t  len;
};

struct vuln_edit_arg {
    uint32_t id;
    char     *buf;
    uint32_t  len;
};

struct vuln_obj {
    uint32_t id;
    uint32_t size;
    void     *callback;
    void     *data_ptr;   /* points to data[] — exploitable */
    char     data[40];
};

#define MAX_OBJS 64

static struct vuln_obj *objs[MAX_OBJS];
static DEFINE_MUTEX(vuln_lock);

static int vuln_open(struct inode *inode, struct file *file) {
    return 0;
}

static int vuln_release(struct inode *inode, struct file *file) {
    return 0;
}

static long vuln_ioctl(struct file *file, unsigned int cmd, unsigned long arg) {
    switch (cmd) {
    case VULN_ALLOC: {
        struct vuln_alloc_arg a;
        if (copy_from_user(&a, (void *)arg, sizeof(a)))
            return -EFAULT;

        if (a.id >= MAX_OBJS)
            return -EINVAL;

        struct vuln_obj *obj = kmalloc(sizeof(struct vuln_obj), GFP_KERNEL);
        if (!obj)
            return -ENOMEM;

        obj->id       = a.id;
        obj->size     = sizeof(struct vuln_obj);
        obj->callback = NULL;
        obj->data_ptr = obj->data;
        memset(obj->data, 0, sizeof(obj->data));

        mutex_lock(&vuln_lock);
        if (objs[a.id]) {
            kfree(objs[a.id]);
        }
        objs[a.id] = obj;
        mutex_unlock(&vuln_lock);

        return 0;
    }

    case VULN_FREE: {
        uint32_t id;
        if (copy_from_user(&id, (void *)arg, sizeof(id)))
            return -EFAULT;

        if (id >= MAX_OBJS)
            return -EINVAL;

        /* BUG: We free the object but don't NULL the pointer.
         * This creates a dangling reference that VULN_USE or
         * VULN_EDIT can still access — classic UAF. */
        mutex_lock(&vuln_lock);
        if (objs[id]) {
            kfree(objs[id]);
            /* Missing: objs[id] = NULL; */
        }
        mutex_unlock(&vuln_lock);

        return 0;
    }

    case VULN_USE: {
        struct vuln_use_arg u;
        if (copy_from_user(&u, (void *)arg, sizeof(u)))
            return -EFAULT;

        if (u.id >= MAX_OBJS)
            return -EINVAL;

        /* BUG: No lock here — races with VULN_FREE.
         * Even with the lock, the pointer is dangling after free. */
        struct vuln_obj *obj = objs[u.id];
        if (!obj)
            return -ENOENT;

        /* UAF: obj may have been freed by a concurrent VULN_FREE */
        if (obj->callback) {
            void (*cb)(char *, uint32_t) = obj->callback;
            cb(obj->data_ptr, obj->size);
        }

        if (u.buf && u.len) {
            if (copy_to_user(u.buf, obj->data_ptr,
                             min(u.len, (uint32_t)40)))
                return -EFAULT;
        }

        return 0;
    }

    case VULN_EDIT: {
        struct vuln_edit_arg e;
        if (copy_from_user(&e, (void *)arg, sizeof(e)))
            return -EFAULT;

        if (e.id >= MAX_OBJS)
            return -EINVAL;

        /* BUG: Uses dangling pointer — if object was freed and
         * reclaimed, this writes to the reclaimed object's data_ptr
         * which an attacker controls. */
        struct vuln_obj *obj = objs[e.id];
        if (!obj)
            return -ENOENT;

        /* UAF write: writes through obj->data_ptr which may point
         * anywhere if the slot was reclaimed with a fake object */
        if (copy_from_user(obj->data_ptr, e.buf,
                           min(e.len, (uint32_t)40)))
            return -EFAULT;

        return 0;
    }

    default:
        return -EINVAL;
    }
}

static const struct file_operations vuln_fops = {
    .owner          = THIS_MODULE,
    .open           = vuln_open,
    .release        = vuln_release,
    .unlocked_ioctl = vuln_ioctl,
};

static struct class *vuln_class;
static struct device *vuln_device;
static int major_num;

static int __init vuln_init(void) {
    major_num = register_chrdev(0, "vuln_drv", &vuln_fops);
    if (major_num < 0) {
        pr_err("vuln_drv: failed to register chrdev\n");
        return major_num;
    }

    vuln_class = class_create("vuln_drv");
    if (IS_ERR(vuln_class)) {
        unregister_chrdev(major_num, "vuln_drv");
        return PTR_ERR(vuln_class);
    }

    vuln_device = device_create(vuln_class, NULL, MKDEV(major_num, 0),
                                NULL, "vuln_drv");
    if (IS_ERR(vuln_device)) {
        class_destroy(vuln_class);
        unregister_chrdev(major_num, "vuln_drv");
        return PTR_ERR(vuln_device);
    }

    memset(objs, 0, sizeof(objs));
    pr_info("vuln_drv: loaded (major=%d), /dev/vuln_drv created\n", major_num);
    return 0;
}

static void __exit vuln_exit(void) {
    int i;
    for (i = 0; i < MAX_OBJS; i++) {
        if (objs[i]) {
            kfree(objs[i]);
            objs[i] = NULL;
        }
    }
    device_destroy(vuln_class, MKDEV(major_num, 0));
    class_destroy(vuln_class);
    unregister_chrdev(major_num, "vuln_drv");
    pr_info("vuln_drv: unloaded\n");
}

module_init(vuln_init);
module_exit(vuln_exit);
MODULE_LICENSE("GPL");
MODULE_AUTHOR("Training Lab");
MODULE_DESCRIPTION("Intentionally vulnerable driver for UAF exploit training");
